<script setup>
import{onMounted,reactive,ref}from'vue';import AdminLayout from'../../components/admin/AdminLayout.vue';import{adminJson}from'../../services/adminAuth';const saved=ref(''),error=ref(''),form=reactive({bihar_name:'',bihar_description:'',bihar_history:'',activities:'',address:'',contact_phone:'',email:'',facebook:'',youtube:'',google_maps:''});onMounted(async()=>Object.assign(form,await adminJson('/api/admin/website')));async function save(){saved.value='';error.value='';try{await adminJson('/api/admin/website',{method:'PUT',body:JSON.stringify({settings:form})});saved.value='ওয়েবসাইটের তথ্য সংরক্ষণ হয়েছে।'}catch(e){error.value=e.message}}
</script>
<template><AdminLayout><div class="admin-title"><div><p>কনটেন্ট ব্যবস্থাপনা</p><h1>ওয়েবসাইট তথ্য</h1></div></div><section class="panel content-panel"><form class="management-form wide-form" @submit.prevent="save"><div class="form-section"><h2>বিহারের পরিচিতি</h2><label>বিহারের নাম<input v-model="form.bihar_name" required></label><label>সংক্ষিপ্ত বিবরণ<textarea v-model="form.bihar_description" rows="4"></textarea></label><label>বিহারের ইতিহাস<textarea v-model="form.bihar_history" rows="5"></textarea></label><label>ধর্মীয় কার্যক্রম<textarea v-model="form.activities" rows="4"></textarea></label></div><div class="form-section"><h2>যোগাযোগ</h2><label>ঠিকানা<textarea v-model="form.address" rows="3"></textarea></label><div class="two-inputs"><label>ফোন<input v-model="form.contact_phone"></label><label>ইমেইল<input v-model="form.email" type="email"></label></div><label>Facebook URL<input v-model="form.facebook" type="url"></label><label>YouTube URL<input v-model="form.youtube" type="url"></label><label>Google Maps লিংক/এম্বেড<input v-model="form.google_maps"></label></div><p v-if="saved" class="success-message">{{saved}}</p><p v-if="error" class="login-error">{{error}}</p><button class="admin-button">পরিবর্তন সংরক্ষণ করুন</button></form></section></AdminLayout></template>
